const assert = require('node:assert/strict');
const fs = require('node:fs');
const {pathToFileURL} = require('node:url');
const {chromium} = require(process.env.WS_PLAYWRIGHT_MODULE);
const [base, reference, shots] = process.argv.slice(2);
const key = 'ws.dashboard.workspace-admission.drafts';
(async () => {
 const browser = await chromium.launch({headless:true});
 const page = await browser.newPage({viewport:{width:1440,height:1000},locale:'ko-KR'});
 const errors=[];
 page.on('pageerror', e=>errors.push(e.stack));
 try {
  const paths=await (await fetch(base+'/fixture-control')).json();
  await page.goto(base+'/');
  await page.locator('.rws-unreg').waitFor({state:'attached'});
  await page.evaluate(()=>document.documentElement.classList.add('rail-open'));
  const panel=page.locator('details.rws-unreg');
  assert.equal(await page.locator('#rlist > .rws').count(),1);
  assert.equal(await panel.getAttribute('open'),null);
  assert.equal(await page.locator('.unreg-count').innerText(),'30');
  async function shot(name) {
   const box=await page.locator('#rail').boundingBox();
   await page.screenshot({path:shots+'/'+name+'.png',clip:{x:Math.max(0,box.x),y:Math.max(0,box.y),width:box.width,height:box.height}});
  }
  async function noOverflow() {
   const data=await page.evaluate(()=>['#rail','#rlist','.rws-unreg','.unreg-list'].map(s=>{
    const e=document.querySelector(s);return {s,scroll:e.scrollWidth,client:e.clientWidth};
   }));
   for(const x of data) assert.ok(x.scroll<=x.client+1,JSON.stringify(x));
  }
  async function toastAboveRailFoot() {
   await page.waitForFunction(()=>!!document.querySelector('#rail > .rtoast.on'));
   await page.waitForTimeout(230);
   const geometry=await page.evaluate(()=>{
    const rect=e=>e&&e.getBoundingClientRect();
    return {toast:rect(document.querySelector('#rail > .rtoast.on')),rail:rect(document.querySelector('#rail')),
      foot:rect(document.querySelector('#rail .rfoot')),cap:rect(document.querySelector('#rail .rcap:not([hidden])'))};
   });
   assert.ok(geometry.toast.left>=geometry.rail.left && geometry.toast.right<=geometry.rail.right);
   assert.ok(geometry.toast.bottom<=geometry.foot.top+1,'toast above rail foot');
   if(geometry.cap) assert.ok(geometry.toast.bottom<=geometry.cap.top+1,'toast above Apply capsule');
  }
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','dark'));
  await noOverflow();await shot('rail-pending-dark');
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','light'));
  await noOverflow();await shot('rail-pending-light');
  await panel.locator('summary.unreg-sum').click();
  assert.ok(await panel.getAttribute('open')!==null);
  assert.equal(await page.locator('.unreg-row').count(),30);
  assert.equal(await page.locator('#unreg-filter').count(),1);
  await page.locator('#unreg-filter').fill('temp-root-01');
  assert.equal(await page.locator('.unreg-row:visible').count(),1);
  assert.equal(await page.locator('#unreg-filter').evaluate(e=>document.activeElement===e),true);
  let oldGen=await page.locator('#rlist').getAttribute('data-lgen');
  await (await fetch(base+'/fixture-control?op=refresh')).json();
  await page.waitForFunction(old=>document.querySelector('#rlist')?.getAttribute('data-lgen')!==old,oldGen);
  assert.equal(await page.locator('#unreg-filter').inputValue(),'temp-root-01');
  assert.equal(await page.locator('#unreg-filter').evaluate(e=>document.activeElement===e),true);
  await page.locator('#unreg-reject-all').click();
  assert.equal(await page.locator('.unreg-row:visible .tg.rj').getAttribute('aria-pressed'),'true');
  await page.locator('#unreg-reject-all').click();
  assert.equal(await page.locator('.unreg-row:visible .tg.rj').getAttribute('aria-pressed'),'false');
  await page.locator('#unreg-filter').fill('');
  await page.locator('.unreg-list').evaluate(e=>e.scrollTop=100);
  const listTop=await page.locator('.unreg-list').evaluate(e=>e.scrollTop);
  oldGen=await page.locator('#rlist').getAttribute('data-lgen');
  await (await fetch(base+'/fixture-control?op=refresh')).json();
  await page.waitForFunction(old=>document.querySelector('#rlist')?.getAttribute('data-lgen')!==old,oldGen);
  assert.ok((await page.locator('.unreg-list').evaluate(e=>e.scrollTop))>=listTop-1);
  const first=page.locator('.unreg-row[data-unreg-path='+JSON.stringify(paths[0])+']');
  await first.locator('.unreg-scount').click();
  assert.equal(await first.locator('.unreg-slink').count(),1);
  assert.ok((await first.locator('.unreg-slink').getAttribute('href')).startsWith('/s/'));
  const linkPage=await browser.newPage({viewport:{width:1440,height:1000}});
  const linkErrors=[];linkPage.on('pageerror',e=>linkErrors.push(e.message));
  await linkPage.goto(base+'/');
  await linkPage.evaluate(()=>document.documentElement.classList.add('rail-open'));
  await linkPage.locator('details.rws-unreg > summary').click();
  await linkPage.locator('.unreg-row[data-unreg-path='+JSON.stringify(paths[0])+'] .unreg-scount').click();
  await linkPage.locator('.unreg-row[data-unreg-path='+JSON.stringify(paths[0])+'] .unreg-slink').click();
  await linkPage.waitForURL(base+'/s/session00');
  assert.equal(linkErrors.length,0,linkErrors.join('\n'));
  await linkPage.close();
  oldGen=await page.locator('#rlist').getAttribute('data-lgen');
  const refresh=page.waitForResponse(r=>r.url()===base+'/rail/refresh');
  await page.locator('#railref').click();await refresh;
  await page.waitForFunction(old=>document.querySelector('#rlist')?.getAttribute('data-lgen')!==old,oldGen);
  assert.ok(await panel.getAttribute('open')!==null,'expanded fold retained after refresh');
  assert.equal(await first.locator('.unreg-scount').getAttribute('aria-expanded'),'true');
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','dark'));
  await noOverflow();await shot('rail-expanded-dark');
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','light'));
  await noOverflow();await shot('rail-expanded-light');
  await page.setViewportSize({width:700,height:1000});
  await noOverflow();await shot('rail-expanded-700-light');
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','dark'));
  await noOverflow();
  await page.setViewportSize({width:1440,height:1000});
  await page.addStyleTag({content:'.rail{width:280px!important}'});
  await noOverflow();await shot('rail-expanded-280-light');
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','dark'));
  await noOverflow();
  await page.addStyleTag({content:'.rail{width:340px!important}'});
  await first.locator('.tg.ap').click();
  assert.equal(await first.locator('.tg.ap').getAttribute('aria-pressed'),'true');
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),key)).length,1);
  assert.equal(await page.locator('.rcap').isVisible(),true);
  let applied=page.waitForResponse(r=>r.url()===base+'/rail/workspaces/admission');
  await page.locator('[data-admission-apply]').click();
  assert.equal((await applied).status(),200);
  await page.waitForFunction(p=>!!document.querySelector('#rlist > .rws[data-ws='+JSON.stringify(p)+']'),paths[0]);
  assert.equal(await page.locator('#rlist > .rws').count(),2);
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),key)).length,0);
  await toastAboveRailFoot();
  const second=page.locator('.unreg-row[data-unreg-path='+JSON.stringify(paths[1])+']');
  await second.locator('.tg.rj').click();
  applied=page.waitForResponse(r=>r.url()===base+'/rail/workspaces/admission');
  await page.locator('[data-admission-apply]').click();assert.equal((await applied).status(),200);
  await page.locator('#unreg-rrej > summary').click();
  await page.locator('.rrej-row[data-ws-rej-path='+JSON.stringify(paths[1])+']').waitFor();
  await shot('rail-rejected-expanded-dark');
  applied=page.waitForResponse(r=>r.url()===base+'/rail/workspaces/admission');
  await page.locator('.rrej-row[data-ws-rej-path='+JSON.stringify(paths[1])+'] .unreg-undo').click();
  assert.equal((await applied).status(),200);
  await second.waitFor();
  await second.locator('.tg.rj').click();
  await page.locator('[data-admission-clear]').click();
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),key)).length,0);
  const worktreeKey='ws.dashboard.worktree-admission.drafts';
  await page.evaluate(k=>localStorage.setItem(k,JSON.stringify([{repository:'/tmp/fixture-repo',path:'/tmp/fixture-worktree',revision:'fixture',action:'approve'}])),worktreeKey);
  await page.reload();
  await page.evaluate(()=>document.documentElement.classList.add('rail-open'));
  await page.locator('.admission-missing').waitFor();
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),worktreeKey)).length,1);
  await page.locator('details.rws-unreg > summary').click();
  await second.locator('.tg.ap').click();
  const workspaceResponse=page.waitForResponse(r=>r.url()===base+'/rail/workspaces/admission');
  const worktreeResponse=page.waitForResponse(r=>r.url()===base+'/rail/worktrees/admission');
  await page.locator('[data-admission-apply]').click();
  assert.equal((await workspaceResponse).status(),200);
  assert.equal((await worktreeResponse).status(),409);
  await page.waitForFunction(()=>document.querySelector('#rail > .rtoast.on')?.textContent.includes('워크트리'));
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),worktreeKey)).length,1);
  const third=page.locator('.unreg-row[data-unreg-path='+JSON.stringify(paths[2])+']');
  await third.locator('.tg.ap').click();
  await (await fetch(base+'/fixture-control?op=refuse')).json();
  const refused=page.waitForResponse(r=>r.url()===base+'/rail/workspaces/admission');
  await page.locator('[data-admission-apply]').click();
  assert.equal((await refused).status(),409);
  await page.waitForFunction(()=>document.querySelector('#rail > .rtoast.on')?.textContent.includes('모두 적용되지'));
  await toastAboveRailFoot();
  assert.equal(await (await fetch(base+'/fixture-control?op=calls')).json(),1,'refused workspace batch does not send worktree batch');
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),key)).length,1);
  await (await fetch(base+'/fixture-control?op=allow')).json();
  await page.locator('[data-admission-clear]').click();
  await third.locator('.tg.ap').click();
  await (await fetch(base+'/fixture-control?op=empty')).json();
  await page.reload();
  await page.locator('.rail-empty-guide').waitFor({state:'attached'});
  await page.evaluate(()=>{document.documentElement.classList.add('rail-open');document.documentElement.setAttribute('data-theme','light');});
  assert.equal(await page.locator('.rail-empty-hint').count(),1);
  assert.equal(await page.locator('details.rws-unreg').getAttribute('open'),null);
  await shot('rail-empty-light');
  await page.evaluate(()=>document.documentElement.setAttribute('data-theme','dark'));
  await shot('rail-empty-dark');
  assert.equal(await page.locator('.rail-empty-add').count(),1);
  assert.equal(await page.locator('#rlist > .rws').count(),0);
  await (await fetch(base+'/fixture-control?op=hide')).json();
  await page.waitForFunction(()=>document.querySelectorAll('.unreg-row').length===0);
  assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)||'[]'),key)).length,1);
  assert.equal(await page.locator('.rcap').isVisible(),false);
  assert.equal(errors.length,0,errors.join('\n'));
  // The approved mockup is captured with the same visual states for review.
  const mock=await browser.newPage({viewport:{width:1440,height:1000}});
  await mock.goto(pathToFileURL(reference).href);
  await mock.evaluate(()=>window.__railMockup.setState({scenario:'flood',theme:'dark',unregOpen:false}));
  await mock.screenshot({path:shots+'/mockup-pending-dark.png'});
  await mock.evaluate(()=>window.__railMockup.setState({scenario:'flood',theme:'light',unregOpen:true,unregRejOpen:true}));
  await mock.screenshot({path:shots+'/mockup-expanded-light.png'});
  console.log('workspace admission browser: flood, filter, drafts, apply, undo, clear, SSE, overflow and screenshots passed');
 } finally {await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
